'use strict';
(() => {
  const pages=['research','options','quality','risk','replay','paper'];
  const node=id=>document.getElementById(id);
  const escape=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=(v,d=2)=>v==null?'—':Number(v).toLocaleString('en-IN',{maximumFractionDigits:d});
  const isoDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  // IST has no daylight-saving offset. Reuse formatters instead of constructing
  // one per historical minute on every incoming live tick.
  const chartDay=timestamp=>new Date((timestamp+19800)*1000).toISOString().slice(0,10);
  let candleCache=null,chartModelCache=null,showEma20=true,showEma50=true;
  const line=(a,b)=>`<div class="research-line"><span>${escape(a)}</span><span>${escape(b)}</span></div>`;
  let data=null,symbol='nifty',timeframe=5,selected=null,requestId=0,current='research',loading=false,session=null,sessionLoading=false,sessionMessage='Start live to load today’s closed candles',liveTick=null,riskDraft={},riskResult='',selectionNotice='',selectionPending=false,riskRevision=0,activeSetup='opening_range',liveOptions=new Map();
  async function get(path,body){const response=await window.thetaApiFetch('/api/research/'+path,{method:body===undefined?'GET':'POST',signal:AbortSignal.timeout(120000),headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const value=await window.thetaReadResponse(response);if(!response.ok)throw Error(typeof value.detail==='string'?value.detail:'Check the required fields and dates.');return value;}
  const notify=text=>{const el=node('research-message');if(el)el.textContent=text;};
  function toolbar(){return `<div class="desk-commandbar"><div class="research-toolbar"><label>Underlying <select id="research-symbol"><option value="nifty" ${symbol==='nifty'?'selected':''}>NIFTY</option><option value="banknifty" ${symbol==='banknifty'?'selected':''}>BANKNIFTY</option></select></label><button class="button secondary" id="research-refresh">Read saved data</button><span class="freshness">${escape(data?.candle_freshness?.state||'Not loaded')} · quote ${escape(data?.chain?.status||'Not loaded')}</span></div><section id="research-live-panel" class="research-section"><div class="research-tabs"><button class="button" id="research-live-start">Start live</button><button class="button secondary" id="research-live-stop">Stop live</button><span id="research-live-state" role="status">Disconnected</span></div><div id="research-live-prices" class="research-strip"></div><details ${current==='options'?'open':''}><summary>Live option quotes / observed LTP</summary><svg id="research-live-chart" class="research-chart" role="img" aria-label="Observed live underlying LTP; not full-session candles" hidden></svg><div id="research-live-contracts" class="table-wrap"></div></details></section></div><details class="desk-source-details"><summary>Source times &amp; live data details</summary><div class="research-meta">${escape(data?.server_time||'')} · Saved-data freshness above; live stream status beside controls. Receipt time is not an exchange quote timestamp.</div><p class="research-help">Live LTP / last-trade time, options bid/ask and OI. Page must stay connected. Historical collection is independent. Quote timestamp / Greeks eligibility are not inferred from LTT.</p></details><div id="research-message" role="status" class="research-result" aria-live="polite"></div>`;}
  function foundationStrip(){
    const setup=data?.setups?.find(s=>s.setup===activeSetup),c=data?.chain||{};
    const status=selectionPending?'UPDATING':({DATA_UNAVAILABLE:'DATA NOT READY',NO_TRADE:'NO TRADE',WAIT:'SETUP FORMING',CONFIRM:'RESEARCH TRIGGER'}[setup?.state]||'AWAITING DATA');
    const gaps=setup?.missing?.length;
    return `<section class="foundation-strip" aria-label="Research readiness"><div class="foundation-cell"><span>DECISION</span><strong class="foundation-decision">${escape(status)}</strong><small>${gaps?escape(gaps)+' missing data checks':'Rule validation pending'}</small></div><div class="foundation-cell"><span>CLOSED CANDLES</span><strong>${escape(data?.candle_freshness?.state||'NOT LOADED')}</strong><small>Source close · ${escape(data?.latest_candle?.closed_at||'Unavailable')}</small></div><div class="foundation-cell"><span>OPTION CHAIN</span><strong>${escape(c.status||'NOT LOADED')}</strong><small>Exchange time · ${escape(c.exchange_at||'Unavailable')}</small></div><div class="foundation-cell"><span>OI PCR · SNAPSHOT</span><strong>${fmt(c.pcr_oi)}</strong><small>Context only · no directional score</small></div></section>`;
  }
  function shell(content,aside=''){const validator=['research','quality'].includes(current)?`<section id="research-data-validator" class="research-section" aria-label="Live data validator">${validatorCard(data?.data_validator)}</section>`:'';return toolbar()+(current==='quality'?validator:'')+`<div class="research-layout"><div class="research-main">${content}</div><aside class="research-aside">${current==='research'?foundationStrip()+validator:''}${aside||context()}<section id="workflow-aside" class="research-section"></section></aside></div>`;}
  function validatorCard(v){return `<h2>Live data validator · ${escape(v?.state||'NOT CHECKED')}</h2><p>${escape(v?.checked_at||'Awaiting server checks')} · ${escape(v?.blocked_checks??'—')} blocked checks · Refreshes every 15s</p><details><summary>Checks, gaps &amp; source times</summary><div class="table-wrap"><table class="research-table"><thead><tr><th>Check</th><th>State</th><th>Evidence</th></tr></thead><tbody>${(v?.checks||[]).map(c=>`<tr><td>${escape(c.check)}</td><td>${escape(c.state)}</td><td>${escape(c.detail)} ${escape(c.expected_minutes!==undefined?`${c.observed_minutes}/${c.expected_minutes} minutes · missing ${c.missing_minutes} · conflicts ${c.conflicting_minutes} · duplicates ${c.duplicate_rows}`:'')} ${escape(c.receipt_age_seconds!==undefined?`Receipt age ${fmt(c.receipt_age_seconds)}s`:'')}</td></tr>`).join('')}</tbody></table></div></details><p class="research-help">${escape(v?.scope||'No data certification yet.')} Failed checks block setup confirmation. A PASS is data validation, not a validated trading strategy.</p>`;}
  let validatorLoading=false;
  async function refreshValidator(){
    if(validatorLoading||!['research','quality'].includes(current))return;
    const requested=symbol;validatorLoading=true;
    try{const response=await window.thetaApiFetch('/api/data-validator?symbol='+encodeURIComponent(requested),{signal:AbortSignal.timeout(20000)});const value=await window.thetaReadResponse(response);if(!response.ok)throw Error('Validator unavailable');if(symbol!==requested)return;if(data){data.data_validator=value;if(!value.data_eligible){const confirmed=(data.setups||[]).some(s=>s.state==='CONFIRM');data.setups=(data.setups||[]).map(s=>({...s,state:'DATA_UNAVAILABLE',missing:[...new Set([...(s.missing||[]),'DATA_VALIDATOR_BLOCKED'])],reason_codes:[...new Set([...(s.reason_codes||[]),'DATA_VALIDATOR_BLOCKED'])]}));if(confirmed)render();}}if(node('research-data-validator'))node('research-data-validator').innerHTML=validatorCard(value);}
    catch(e){if(symbol===requested&&node('research-data-validator'))node('research-data-validator').textContent='Live data validator unavailable · previous results are not current. Read saved data to refresh setup checks.';}
    finally{validatorLoading=false;}
  }
  setInterval(refreshValidator,15000);
  function context(){return `<section class="research-section"><h2>Market watch</h2>${(data?.markets?.items||[]).map(r=>line(r.label,(r.price==null?'Unavailable':fmt(r.price))+' · '+r.status)).join('')}<p class="research-help">Global feeds, breadth and events need verified sources. They are not inferred from domestic futures.</p></section>`;}
  function identity(){const c=selected;return c?`${escape(symbol.toUpperCase())} · ${escape(c.expiry)} · ${fmt(c.strike)} ${escape(c.side)} · ID ${escape(c.security_id)} · lot ${escape(c.lot_size)} · ${escape(c.freshness)}`:'No exact option contract selected';}
  function chart(){return `<section class="research-section room-chart"><div class="analysis-heading"><div><h2>${symbol.toUpperCase()} · Price action</h2><p>Closed provider candles · IST</p></div><div class="chart-actions"><button class="button secondary" id="dashboard-chart-focus" type="button" aria-pressed="false">Chart focus</button><button class="button secondary" id="chart-fullscreen" type="button" aria-pressed="false">Fullscreen</button></div></div><div class="research-tabs chart-controls">${[1,5,15,60].map(n=>`<button class="button secondary" data-timeframe="${n}" aria-pressed="${timeframe===n}">${n===60?'1H':n+'m'}</button>`).join('')}<label><input type="checkbox" id="research-ema" ${showEma20?'checked':''}> EMA20</label><label><input type="checkbox" id="research-ema50" ${showEma50?'checked':''}> EMA50</label><div class="chart-actions"><button class="button secondary" id="chart-zoom-out" aria-label="Zoom out">−</button><button class="button secondary" id="chart-zoom-in" aria-label="Zoom in">+</button><button class="button secondary" id="chart-reset">Latest bars</button></div></div><div id="research-chart-readout" class="chart-ohlc" role="status">Loading closed candles…</div><div id="research-chart" class="research-chart price-action-chart" tabindex="0" role="group" aria-label="Interactive provider candlestick chart. Drag to pan, pinch to zoom. Keyboard plus and minus zoom; arrows pan; Home shows latest bars."></div><div id="research-indicator-values" class="indicator-values" aria-label="Authoritative indicator values"></div><div id="research-chart-live" class="research-meta" role="status"></div><div class="chart-source"><button class="button secondary" id="research-session-refresh" ${sessionLoading?'disabled':''}>Refresh candles &amp; breadth</button><span class="research-meta">${identity()}</span></div><div id="research-session-state" class="research-meta" role="status">${escape(sessionMessage)}</div><details class="desk-chart-notes"><summary>Candle methodology &amp; data gaps</summary><p class="research-help">Only complete provider bars; missing minutes stay gaps. Backend EMA20/50, RSI14 and ADX14 use the same closed candles as the decision engine. Gaps reset warm-up. ORB = 09:15–09:30, only after all 15 minutes. Last 15 minutes are not a complete 1H candle. Dashed LTP is an observation, not a forming candle. Auto-refresh every 60s while live is active. RSI/ADX are context, not new entry rules. VWAP is exact-futures context below; index volume is not used.</p></details><small class="chart-attribution">Charts by <a href="https://www.tradingview.com/" target="_blank" rel="noopener noreferrer">TradingView</a> · Lightweight Charts™ 5.2.1 · <a href="/static/vendor/lightweight-charts-NOTICE.txt" target="_blank" rel="noopener">Copyright &amp; attribution</a></small></section>`;}
  const reasons={DATA_VALIDATOR_BLOCKED:'Live data validator mein checks blocked hain; Data Quality dekhein',WORKSPACE_REFRESH_FAILED:'Workspace refresh failed; setup checks unavailable',
    HTF_WARMUP_REQUIRED:'1H trend ke liye candles kam hain',MTF_WARMUP_REQUIRED:'15m trend ke liye candles kam hain',HTF_SIDEWAYS:'1H trend sideways hai',HTF_CONFLICT:'1H aur 15m trend alag hain',HTF_ALIGNED:'1H aur 15m trend aligned hain',
    OPENING_RANGE_INCOMPLETE:'09:15–09:30 ki range incomplete hai',RANGE_BREAK_PENDING:'Range ke bahar closed 5m candle ka wait',RANGE_BREAK_OK:'Closed 5m candle ne range + buffer break kiya',RETEST_PENDING:'Range edge par retest ka wait',RETEST_HOLD_OK:'Retest ne range edge hold kiya',FRESH_TRIGGER_PENDING:'Retest/pullback ke baad fresh 5m close ka wait',FRESH_TRIGGER_OK:'Fresh closed 5m trigger mila',LATE_ENTRY:'Retest/trigger ka allowed time nikal gaya',
    PULLBACK_WARMUP_REQUIRED:'Pullback check ke liye candles kam hain',PULLBACK_PENDING:'15m EMA20 par pullback ka wait',PULLBACK_HOLD_OK:'Pullback ne structure hold kiya',STRUCTURE_BROKEN:'Pullback structure toot gaya',CANDLE_GAPS:'Current session mein closed candles missing hain',CANDLES_MISSING:'Provider candles nahi hain',CANDLE_STALE:'Latest candle purani hai',CANDLE_TIME_UNVERIFIED:'Candle ka time verified nahi hai',
    OUTSIDE_ENTRY_WINDOW:'Entry window ke bahar (09:30–15:00 IST)',EVENT_CONTEXT_UNAVAILABLE:'Verified event context nahi hai',BREADTH_UNAVAILABLE:'Recent constituent participation nahi hai',PARTICIPATION_WEAK:'Direction ke saath participation kam hai',ROOM_TO_LEVEL_UNAVAILABLE:'Agla obstacle / risk distance establish nahi hua',RESISTANCE_TOO_CLOSE:'Agla obstacle minimum R se paas hai',
    OPTION_QUOTE_UNAVAILABLE:'Exact option select karein / quote missing hai',CONTRACT_UNVERIFIED:'Contract ya lot master verified nahi hai',OPTION_TIME_UNVERIFIED:'Option quote time verified / fresh nahi hai',OPTION_SIDE_CONFLICT:'Selected CE/PE setup direction se match nahi karta',BID_ASK_UNAVAILABLE:'Valid bid/ask nahi hai',SPREAD_TOO_WIDE:'Bid/ask spread allowed limit se zyada hai',LIQUIDITY_TOO_LOW:'OI ya volume allowed minimum se kam hai',EXPIRY_DAY_BLOCKED:'Expiry-day entry rule se blocked hai'
  };
  const explain=code=>reasons[code]||String(code).replaceAll('_',' ').toLowerCase();
  function chainPanel(){
    const c=data?.chain||{},rows=c.contracts||[],strikes=[...new Set(rows.filter(r=>r.expiry===c.expiry).map(r=>r.strike))].sort((a,b)=>a-b);
    const center=strikes.length?(c.spot?strikes.reduce((a,b)=>Math.abs(b-c.spot)<Math.abs(a-c.spot)?b:a):strikes[Math.floor(strikes.length/2)]):null;
    const at=strikes.indexOf(center),visible=strikes.slice(Math.max(0,at-5),at+6);
    const leg=(strike,side)=>rows.find(r=>r.strike===strike&&r.side===side&&r.expiry===c.expiry);
    // A complete same-expiry snapshot is required; missing values never become zero.
    const zoneStrikes=at>=2?strikes.slice(at-2,at+3):[];
    const spotValid=typeof c.spot==='number'&&Number.isFinite(c.spot)&&c.spot>0;
    const zoneRows=zoneStrikes.flatMap(k=>['CE','PE'].map(side=>rows.filter(r=>r.expiry===c.expiry&&r.strike===k&&r.side===side)));
    const zoneValid=spotValid&&!!c.expiry&&zoneStrikes.length===5&&zoneStrikes.every(k=>typeof k==='number'&&Number.isFinite(k))&&zoneRows.length===10&&zoneRows.every(group=>group.length===1&&typeof group[0].delta_oi==='number'&&Number.isFinite(group[0].delta_oi));
    const total=side=>zoneStrikes.reduce((sum,k)=>sum+leg(k,side).delta_oi,0);
    const zone=`<div class="research-section"><h3>5-STRIKE ATM ZONE · ${escape(symbol.toUpperCase())}</h3><div class="research-strip"><span>ATM <b>${spotValid?fmt(center,0):'Unavailable'}</b></span><span>Call OI change <b>${zoneValid?fmt(total('CE'),0):'Unavailable'}</b></span><span>Put OI change <b>${zoneValid?fmt(total('PE'),0):'Unavailable'}</b></span></div><p class="research-help">ATM ±2 returned strikes · ${escape(c.expiry)} · snapshot ${escape(c.status||'unavailable')} · received ${escape(c.received_at)} · exchange ${escape(c.exchange_at)}. OI change is versus previous-day OI, not intraday change.${zoneValid?'':' Requires spot and complete CE and PE OI changes for all five strikes.'}</p></div>`;
    const cells=(r,side)=>r?`<td><button class="chain-pick ${selected?.security_id===r.security_id?'is-selected':''}" data-contract="${escape(r.security_id)}" aria-pressed="${selected?.security_id===r.security_id}" aria-label="Select ${fmt(r.strike,0)} ${side}">₹${fmt(r.last_price)}</button><small>${fmt(r.bid)} / ${fmt(r.ask)} · spread ${fmt(r.spread_pct)}%</small></td><td>${fmt(r.oi,0)}<small>Δ ${fmt(r.delta_oi,0)}</small></td><td>${fmt(r.iv)}<small>Δ ${fmt(r.greeks?.delta)}</small></td>`:'<td>Unavailable</td><td>—</td><td>—</td>';
    return `<section class="research-section room-chain"><h2>CE / PE comparison · same saved snapshot</h2><div class="research-strip"><span>Expiry <b>${escape(c.expiry)}</b></span><span>OI PCR <b>${fmt(c.pcr_oi)}</b></span><span>Volume PCR <b>${fmt(c.pcr_volume)}</b></span><button class="button secondary" id="research-chain">Refresh chain snapshot</button></div><div class="research-meta">${escape(c.status||'Not loaded')} · received ${escape(c.received_at)} · exchange ${escape(c.exchange_at)}</div>${zone}<div class="table-wrap"><table class="research-table compact-chain"><thead><tr><th colspan="3">CALL · CE</th><th>Strike</th><th colspan="3">PUT · PE</th></tr><tr><th>Premium / bid–ask</th><th>OI / change</th><th>IV / delta</th><th>${c.spot?'ATM ±5':'Center ±5'}</th><th>Premium / bid–ask</th><th>OI / change</th><th>IV / delta</th></tr></thead><tbody>${visible.map(k=>`<tr class="${k===center?'chain-atm':''}">${cells(leg(k,'CE'),'CE')}<th>${fmt(k,0)}${k===center?(c.spot?'<small>ATM</small>':'<small>Spot unavailable</small>'):''}</th>${cells(leg(k,'PE'),'PE')}</tr>`).join('')||'<tr><td colspan="7">No snapshot. Refresh chain to load available contracts.</td></tr>'}</tbody></table></div><p class="research-help">Premium buttons select the exact contract. PCR uses all returned strikes. ΔOI = current minus previous-day OI. Stale values are historical context; IV/Greeks remain hidden when unverified.</p></section>`;
  }
  function setupPanel(s){
    const state=selectionPending?'Updating contract checks':({DATA_UNAVAILABLE:'WAIT · Data incomplete',NO_TRADE:'NO TRADE · Rule blocked',WAIT:'WAIT · Setup forming',CONFIRM:'Trigger met · Unvalidated research'}[s.state]||s.state);
    return `<section class="research-section"><h2>${s.setup==='opening_range'?'Opening range + retest':'Trend pullback'}</h2>${patternPanel(s.price_pattern)}<div class="decision-kicker">DECISION ENGINE · RESEARCH</div><h3>Evidence eligibility</h3><div class="research-state">${escape(state)}</div><p class="research-help">${escape(s.side||'Direction unavailable')} · ${escape(s.rule_version)}</p>${setupChecks(s)}${line('Structure / range reference',fmt(s.reference_level))}${line('Underlying trigger price',fmt(s.trigger_price))}${line('Underlying invalidation',fmt(s.underlying_invalidation))}<details><summary>Rule codes</summary><p class="research-meta">${escape((s.reason_codes||[]).join(' · '))}</p></details></section>`;
  }
  function patternPanel(p){
    if(!p)return '';
    const label={DATA_UNAVAILABLE:'Price pattern · data unavailable',NO_PATTERN:'Price pattern · rules conflict',FORMING:'Price pattern · forming',TRIGGER_OBSERVED:'Price trigger observed · research only'}[p.state]||'Price pattern unavailable';
    return `<div class="price-pattern"><h3>${escape(label)}</h3><div>${escape(p.side||'Direction unavailable')}</div><p class="research-help">${escape(p.basis)} · ${escape(p.clock)}</p><ul class="setup-reasons">${(p.reason_codes||[]).map(code=>`<li>${escape(explain(code))}</li>`).join('')}</ul></div>`;
  }
  function setupChecks(s){
    const actions={EVENT_CONTEXT_UNAVAILABLE:'Verified event-calendar source is not connected. Refreshing prices cannot clear this gate.',OPTION_TIME_UNVERIFIED:'Provider does not supply a separate exchange quote timestamp here. A recent trade or receipt time cannot certify bid/ask freshness.',BREADTH_UNAVAILABLE:'Start live to request current constituent breadth; all required members must pass freshness checks.',CANDLE_STALE:'Start live for current-session closed provider candles.',CANDLES_MISSING:'Start live for provider candles; historical collection runs independently.',OPTION_QUOTE_UNAVAILABLE:'Select a CE or PE premium in the comparison table.',OUTSIDE_ENTRY_WINDOW:'Research entry window is 09:30–15:00 IST.',SPREAD_TOO_WIDE:'Select an adequately liquid contract or wait for spread to narrow; the threshold stays enforced.'};
    const groups=[['Data required',s.missing],['Rule blocked',s.failed],['Setup forming',s.pending],['Conditions met',s.passed]];
    if(!groups.some(([,codes])=>codes?.length))return `<ul class="setup-reasons">${(s.reason_codes||[]).map(r=>`<li>${escape(explain(r))}</li>`).join('')}</ul>`;
    return groups.filter(([,codes])=>codes?.length).map(([label,codes])=>`<div class="setup-checks"><h3>${label}</h3><ul class="setup-reasons">${codes.map(r=>`<li>${escape(explain(r))}${actions[r]?`<small>${escape(actions[r])}</small>`:''}</li>`).join('')}</ul></div>`).join('');
  }
  function selectedPanel(){return `<section class="research-section selected-option"><h2>Selected option · fixed identity</h2><div class="research-identity">${identity()}</div><div id="selected-live-observation" role="status"></div>${selectionNotice?`<p role="status" class="research-help">${escape(selectionNotice)}</p>`:''}${line('Snapshot premium',fmt(selected?.last_price))}${line('Bid / ask',selected?fmt(selected.bid)+' / '+fmt(selected.ask):'—')}${line('Spread %',fmt(selected?.spread_pct))}<p class="research-help">Selection stays on this security ID. ATM highlighting can move. Underlying invalidation is not a premium stop.</p></section>`;}
  function renderRoom(){const setups=data?.setups||[],ind=data?.indicators||{},latest=data?.latest_candle;return shell(`<div class="research-strip"><span>Last closed ${symbol.toUpperCase()} <b>${fmt(latest?.close)}</b></span><span>1H ${escape(ind['60']?.bias)}</span><span>15m ${escape(ind['15']?.bias)}</span></div><div class="room-workbench">${chart()}${chainPanel()}</div><section class="research-section" id="dashboard-analysis" aria-label="Eight analysis levels"></section><details class="research-section"><summary>Session high / low</summary><div id="research-levels"></div><p class="research-help">Only loaded provider candles; gaps can leave extremes incomplete.</p></details>`,`<label class="room-setup-label">Setup<select id="room-setup"><option value="opening_range" ${activeSetup==='opening_range'?'selected':''}>Opening range + retest</option><option value="trend_pullback" ${activeSetup==='trend_pullback'?'selected':''}>Trend pullback</option></select></label>`+setups.filter(s=>s.setup===activeSetup).map(setupPanel).join('')+selectedPanel()+`<section class="research-section room-risk"><h2>Premium stop → ₹ risk</h2><p class="research-help">Enter a premium stop, target and explicit cost assumptions. This is planning, not an entry confirmation.</p>${riskForm()}</section>`);}
  function renderOptions(){const c=data?.chain||{},rows=c.contracts||[];let spot=c.spot;const strikes=[...new Set(rows.map(r=>r.strike))];let center=spot?strikes.reduce((a,b)=>Math.abs(b-spot)<Math.abs(a-spot)?b:a,strikes[0]):strikes[Math.floor(strikes.length/2)];const index=strikes.indexOf(center),near=new Set(strikes.slice(Math.max(0,index-5),index+6));return shell(`<section class="research-section"><div class="research-strip"><span>Expiry <b>${escape(c.expiry)}</b></span><span>OI PCR <b>${fmt(c.pcr_oi)}</b></span><span>Volume PCR <b>${fmt(c.pcr_volume)}</b></span></div><div class="research-help">${escape(c.pcr_basis||'No chain saved.')} · Both PCR values use all returned strikes, not only the visible ±5 range.</div><button class="button secondary" id="research-chain">Fetch current expiry snapshot</button><p class="research-help">Manual bounded request. Does not establish continuous PCR history or fresh exchange timestamps.</p><div class="research-meta">Received ${escape(c.received_at)} · exchange ${escape(c.exchange_at)} · ${escape(c.status)}</div></section><section class="research-section"><h2>Near-ATM contracts · ±5 returned strikes</h2><div class="table-wrap"><table class="research-table"><thead><tr><th>Contract</th><th>LTP ₹</th><th>Bid / ask</th><th>Spread %</th><th>OI / ΔOI</th><th>Volume</th><th>IV / delta</th><th>Liquidity</th></tr></thead><tbody>${rows.filter(r=>near.has(r.strike)).map(r=>`<tr><td><button class="button secondary" data-contract="${escape(r.security_id)}">${fmt(r.strike,0)} ${r.side}</button></td><td>${fmt(r.last_price)}</td><td>${fmt(r.bid)} / ${fmt(r.ask)}</td><td>${fmt(r.spread_pct)}</td><td>${fmt(r.oi,0)} / ${fmt(r.delta_oi,0)}</td><td>${fmt(r.volume,0)}</td><td>${fmt(r.iv)} / ${fmt(r.greeks?.delta)}</td><td>${escape(r.liquidity)}</td></tr>`).join('')||'<tr><td colspan="8">No saved option chain. Use the bounded fetch above.</td></tr>'}</tbody></table></div></section>`, `<section class="research-section"><h2>Selected contract</h2><div class="research-identity">${identity()}</div>${line('Bid / ask',selected?fmt(selected.bid)+' / '+fmt(selected.ask):'—')}${line('Spread %',fmt(selected?.spread_pct))}${line('IV',fmt(selected?.iv))}${line('Delta',fmt(selected?.greeks?.delta))}${line('Gamma',fmt(selected?.greeks?.gamma,5))}${line('Theta',fmt(selected?.greeks?.theta))}${line('Vega',fmt(selected?.greeks?.vega))}${line('Master identity',selected?.identity_verified?'Verified in current master':'Unverified')}${line('IV percentile','History unverified')}${line('PCR trend','Continuous cadence unverified')}<p class="research-help">${escape(c.greeks_reason||'Select an exact contract.')} OI change means current OI minus previous-day OI. No directional forecast is derived from PCR.</p></section>`);}
  function renderQuality(){const h=data?.history||{};const jobs=data?.collection?.jobs||[];return shell(`<section class="research-section"><h2>Data contracts</h2><div class="table-wrap"><table class="research-table"><thead><tr><th>Dataset</th><th>Maximum age</th><th>Required identity / time</th></tr></thead><tbody>${Object.entries(data?.policies||{}).map(([k,v])=>`<tr><td>${escape(k)}</td><td>${v.max_age_seconds}s</td><td>${escape((v.required||[]).join(', ')||v.timestamp)}</td></tr>`).join('')}</tbody></table></div><p class="research-help">Live freshness requires exchange time and received time; future timestamps fail closed. Closed markets and historical ranges are labelled historical, not certified fresh.</p></section><section class="research-section"><h2>Retained history view</h2>${line('Read scope',h.read_scope||'Not loaded')}${line('Conflicting minutes excluded',h.conflicting_minutes??'—')}${line('Invalid record IDs',(h.invalid_record_ids||[]).join(', ')||'None in scanned records')}${line('Exchange-calendar certification','Not established')}<form id="research-coverage" class="research-form"><label>From<input name="start" type="date" required></label><label>To exclusive<input name="end" type="date" required></label><button class="button secondary" type="submit">Check 1–31 day coverage</button></form><div id="research-coverage-result" class="research-result" role="status"></div></section><section class="research-section"><h2>Background collection · read only</h2>${jobs.map(j=>line(j.id.slice(0,8),j.state+' · '+j.items_assessed+' items · '+j.rows_saved+' rows')).join('')||'<p>No jobs returned.</p>'}<p class="research-help">${escape(data?.collection?.next_cursor?'More jobs exist; open Collect all data for pagination.':'')} Worker: ${escape(JSON.stringify(data?.worker||{}))}</p></section>`, `<section class="research-section"><h2>Connection & gates</h2>${line('Token last check',data?.credential_check?.status||'Not checked')}${line('Expiry (Dhan)',data?.credential_check?.token_validity_reported||'Not reported')}${Object.entries(data?.availability||{}).map(([k,v])=>line(k,v)).join('')}${line('Option P&L readiness','Blocked')}${line('Live orders','Disabled')}</section>`);}
  const riskFields=[['entry','Entry premium ₹ · assumption'],['stop','Stop premium ₹'],['target','Target premium ₹ · assumption'],['risk_rupees','Per-trade risk ₹'],['capital','Available capital ₹'],['daily_loss_cap','Daily loss cap ₹'],['realised_loss','Realised loss today ₹'],['open_risk','Reserved open risk ₹'],['lot_size','Verified lot size'],['brokerage_roundtrip','Round-trip brokerage ₹'],['exchange_roundtrip_per_lot','Exchange charges / lot ₹'],['stt_exit_rate','STT exit rate (decimal)'],['sebi_turnover_rate','SEBI turnover rate (decimal)'],['gst_rate','GST rate (decimal)'],['stamp_entry_rate','Stamp entry rate (decimal)'],['slippage_per_unit','Round-trip slippage / unit ₹'],['spread_per_unit','Spread allowance / unit ₹']];
  function riskForm(){return `<form id="research-risk" class="research-form">${riskFields.map(([k,t],i)=>`${i===9&&current==='research'?'<details class="risk-costs wide"><summary>Charges, slippage & verification · required</summary><div class="research-form">':''}<label>${t}<input type="number" step="any" min="${['stop','target','entry','risk_rupees','capital','daily_loss_cap','lot_size'].includes(k)?'0.0001':'0'}" name="${k}" required value="${escape(riskDraft[k]??(k==='entry'?selected?.ask:k==='lot_size'?selected?.lot_size:'' )??'')}"></label>`).join('')}<label>Lot metadata source<input name="lot_source" maxlength="200" required placeholder="Dhan instrument master" value="${escape(riskDraft.lot_source??(selected?.identity_verified?'Dhan current instrument master':''))}"></label><label>Lot verified on<input name="lot_verified_on" type="date" value="${escape(riskDraft.lot_verified_on??(selected?.identity_verified?isoDate():''))}" required></label><label>Contract expiry<input name="expiry" type="date" value="${escape(riskDraft.expiry??(escape(selected?.expiry||'')))}" required></label><label>Costs effective on<input name="costs_effective_on" type="date" value="${escape(riskDraft.costs_effective_on||'')}" required></label><label>Costs source<input name="costs_source" value="${escape(riskDraft.costs_source||'')}" required maxlength="300"></label><label>Expiry-day entry<select name="expiry_day_allowed"><option value="false">Blocked</option><option value="true" ${riskDraft.expiry_day_allowed==='true'?'selected':''}>Explicitly allow</option></select></label>${current==='research'?'</div></details>':''}<button type="submit" class="button">Calculate lots & quantity</button></form><div id="research-risk-result" class="research-result" role="status">${escape(riskResult)}</div><div id="paper-plan-result" class="research-result"></div>`;}
  function renderRisk(){return shell(`<section class="research-section"><h2>Cost-aware position planning</h2><p class="research-help">Enter all assumptions explicitly. No tariff or lot size is silently hardcoded. This estimates risk, not eligibility to enter. Premium stops may gap.</p>${riskForm()}</section><section class="research-section"><h2>Rule specification · ${escape(data?.rule_version)}</h2><p class="research-help">Defaults are research hypotheses, not optimised or validated parameters.</p>${line('Opening range','09:15–09:30 IST; all 15 one-minute bars required')}${line('Breakout','Closed 5m close beyond range + 0.05% buffer')}${line('Retest','Within ±0.05% of range edge; hold, then fresh close beyond retest bar')}${line('Timeout','Retest/trigger within 6 closed 5m bars')}${line('Trend pullback','Aligned 1H/15m EMA20/50; 15m EMA20 touch ±0.05%, hold; 5m trigger')}${line('Participation','Direction-aligned breadth ≥60%; verified current context required')}${line('Option filter','Verified contract/lot, fresh time, spread ≤1%, OI and volume ≥100')}${line('Room / timing','≥1.5R to level, 09:30–15:00; expiry day blocked by default')}${line('States','DATA_UNAVAILABLE → NO_TRADE → WAIT → CONFIRM')}${line('Confirmation','Unvalidated research state; never an order')}</section>`);}
  function renderReplay(){return shell(`<section class="research-section"><h2>Event-clock replay / backtest readiness</h2><p class="research-help">The engine receives only candles closed by the selected clock. Historical receive times stay original for strict evidence checks. Price-pattern replay explicitly assumes each bar is known at its close; ingestion revisions are not simulated. No future bars or reconstructed option quotes enter the engine.</p><form id="research-replay" class="research-form"><label>From<input type="date" name="start" required></label><label>To exclusive<input type="date" name="end" required></label><label>Event clock (IST)<input type="datetime-local" name="clock" required></label><label>Setup<select name="setup"><option value="opening_range">Opening range + retest</option><option value="trend_pullback">Trend pullback</option></select></label><button class="button" type="submit">Run bounded replay</button></form><div id="research-replay-result" role="status" class="research-result"></div><label id="research-replay-slider-label" hidden>Known event<input id="research-replay-slider" type="range" min="0" max="0" value="0" style="width:100%"></label><div id="research-replay-event" class="research-result" role="status"></div></section><section class="research-section"><h2>Option performance gates</h2>${line('Exact contract history','Not certified; rolling ATM is not a fixed contract')}${line('Historical bid/ask','Not established')}${line('Costs + slippage','Explicit model required')}${line('Calendar / regimes','Session calendar and regime labels required')}${line('Walk-forward results','Not available until execution data passes')}${line('Paper validation','50+ actual paper trades across regimes; track deviations')}<p class="research-help">Win rate, expectancy and drawdown remain unavailable. Underlying replay is not an option P&L backtest.</p></section>`);}
  function renderPaper(){return shell(`<section class="research-section"><h2>Paper journal · hypothetical trades and observations</h2><div id="paper-trade-panel"></div><p class="research-help">Immutable observations with rule version and deviation notes. These are not simulated fills or completed paper trades; they do not count toward the 50-trade gate.</p><form id="research-note" class="research-form"><label>Setup<select name="setup"><option value="opening_range">Opening range + retest</option><option value="trend_pullback">Trend pullback</option></select></label><label>Decision<select name="decision">${['WAIT','NO_TRADE','CE_OBSERVED','PE_OBSERVED','EXIT_REVIEW'].map(x=>'<option>'+x+'</option>').join('')}</select></label><label class="wide">Reason / observation<textarea name="note" maxlength="2000" required></textarea></label><label class="wide">Rule deviation<textarea name="deviations" maxlength="2000" placeholder="Any ignored or overridden rule"></textarea></label><button class="button" type="submit">Save observation (Admin required)</button></form><div id="research-notes" role="status"></div><button class="button secondary" id="research-more-notes" hidden>Load more notes</button></section>`);}
  function render(){if(!pages.includes(current))return;window.thetaChartDispose?.();for(const page of pages)if(page!==current)node('page-'+page).innerHTML='';const el=node('page-'+current);el.innerHTML=({research:renderRoom,options:renderOptions,quality:renderQuality,risk:renderRisk,replay:renderReplay,paper:renderPaper}[current])();bind();if(current==='research'){drawChart();renderSelectedLive();}if(current==='paper')loadNotes();window.thetaWorkflowMount?.();window.thetaDashboardMount?.();}
  async function readWorkspace(id,path){
    for(let attempt=0;attempt<2;attempt++){
      try{return await get(path);}catch(error){
        if(id!==requestId||attempt===1||![500,502,503,504].includes(error.status))throw error;
        notify('Saved evidence temporarily unavailable · retrying once…');
        await new Promise(resolve=>setTimeout(resolve,1000));
        if(id!==requestId)throw error;
      }
    }
  }
  async function load(){const id=++requestId;loading=true;notify('Reading saved evidence…');try{const result=await readWorkspace(id,'workspace?symbol='+symbol+'&contract_id='+encodeURIComponent(selected?.security_id||''));if(id!==requestId)return;data=result;if(selected){const fresh=result.chain.contracts.find(c=>c.security_id===selected.security_id);selected=fresh||{...selected,last_price:null,bid:null,ask:null,spread_pct:null,iv:null,greeks:null,freshness:'UNAVAILABLE'};selectionNotice=fresh?'':'Selected contract is absent from this snapshot. Quotes unavailable; choose another contract explicitly.';}selectionPending=false;render();notify('');}catch(e){if(id===requestId){selectionPending=false;selectionNotice='Setup verification failed. Read saved data to retry; no entry is confirmed.';if(data)data={...data,setups:(data.setups||[]).map(s=>({...s,state:'DATA_UNAVAILABLE',price_pattern:{state:'DATA_UNAVAILABLE',reason_codes:['WORKSPACE_REFRESH_FAILED'],basis:'Workspace read failed; prior pattern is not current'},missing:['WORKSPACE_REFRESH_FAILED'],reason_codes:['WORKSPACE_REFRESH_FAILED']}))};render();notify(e.message);}}finally{if(id===requestId)loading=false;}}
  function chartCandles(){
    const old=data?.history?.candles;
    // Workspace is authoritative; a separately retained session must not overwrite it.
    if(data?.indicator_chart)return old||[];
    if(candleCache&&candleCache.old===old&&candleCache.session===session)return candleCache.rows;
    const rows=session?[...(old||[]).filter(r=>chartDay(r.timestamp)!==session.session_date),...session.candles].sort((a,b)=>a.timestamp-b.timestamp):(old||[]);
    candleCache={old,session,rows};return rows;
  }
  function drawChart(){
    const element=node('research-chart');if(!element||!window.thetaChartData)return;
    const rows=chartCandles();
    const pack=data?.indicator_chart,frame=pack?.frames?.[String(timeframe)];
    if(!frame&&(!chartModelCache||chartModelCache.rows!==rows||chartModelCache.timeframe!==timeframe)){chartModelCache={rows,timeframe,model:window.thetaChartData.build(rows,timeframe)};}
    const model=frame?{...pack,...frame,last:frame.bars.findLast(r=>r.close!==undefined)}:chartModelCache.model,setup=data?.setups?.find(s=>s.setup===activeSetup),levels=[...model.levels];
    if(setup&&Number.isFinite(Date.parse(setup.clock))&&chartDay(Date.parse(setup.clock)/1000)===model.loadedDay){
      for(const [title,price,color] of [['Structure',setup.reference_level,'#6c7b8d'],['Observed trigger',setup.trigger_price,'#087f6e'],['Underlying invalidation',setup.underlying_invalidation,'#9b650e']])if(typeof price==='number'&&Number.isFinite(price)&&price>0)levels.push({title,price,color});
    }
    window.thetaChartRender?.(element,{...model,key:symbol+':'+timeframe,minutes:timeframe,source:frame?'Backend closed candles':session&&model.loadedDay===session.session_date?'Current-session refresh':'Historical',showEma20,showEma50,levels,live:liveTick});
    renderIndicatorValues(model,frame?.snapshot,pack);
    node('research-levels').innerHTML=line('Displayed session',model.loadedDay)+line('High / low',fmt(model.loadedHigh)+' / '+fmt(model.loadedLow))+line('Chart exclusions',model.excluded+' invalid / off-grid; '+model.conflicts+' conflicting minutes');
  }
  function renderIndicatorValues(model,snapshot,pack){
    const el=node('research-indicator-values');if(!el)return;
    const age=Date.now()-Date.parse(pack?.clock),expired=!Number.isFinite(age)||age<0||age>90000;
    const fresh=!expired&&data?.candle_freshness?.state==='FRESH';
    const state=!pack?'BACKEND VALUES UNAVAILABLE':!fresh?'HISTORICAL / STALE':snapshot?.state||'MISSING';
    const futures=data?.futures_context||{},futureAge=Date.now()-Date.parse(futures.received_at);
    const vwap=futures.state==='FRESH_CANDLE_APPROXIMATION'&&futureAge>=0&&futureAge<=90000?futures.value:null;
    el.innerHTML=`<div class="indicator-heading"><strong>${timeframe===60?'1H':timeframe+'m'} · ${escape(state)}</strong><small>${escape(pack?.version||'No engine snapshot')} · ${escape(pack?.clock||'')} · ${snapshot?.consecutive_bars||0} consecutive bars · ${snapshot?.missing_buckets||0} missing buckets</small></div><div class="research-strip">${[['EMA20',snapshot?.ema20],['EMA50',snapshot?.ema50],['RSI14',snapshot?.rsi14],['ADX14',snapshot?.adx14],['+DI / −DI',snapshot?fmt(snapshot.plus_di)+' / '+fmt(snapshot.minus_di):null]].map(([label,value])=>`<span>${label} <b>${typeof value==='string'?escape(value):fmt(value)}</b></span>`).join('')}</div><div class="research-strip"><span>ORB15m <b>${fmt(pack?.orb?.high)} / ${fmt(pack?.orb?.low)}</b> · ${escape(pack?.orb?.date)} · ${escape(pack?.orb?.state||'INCOMPLETE')}</span><span>Futures VWAP <b>${fmt(vwap)}</b> · ${escape(futures.expiry)} · ID ${escape(futures.security_id)} · ${escape(vwap===null?'Unavailable / stale':futures.state)}</span></div><p class="research-help">Same backend values as setup checks. RSI/ADX describe momentum; thresholds are not validated entry rules. Futures VWAP uses HLC3 × volume, belongs to a different instrument, and is not drawn on the index scale. Historical values never certify a live signal.</p>`;
  }
  let journalCursor=null;
  async function loadNotes(after=''){try{const r=await get('journal'+(after?'?after='+encodeURIComponent(after):''));if(current!=='paper')return;const html=r.entries.map(n=>`<article class="research-note"><div>${escape(n.input.symbol.toUpperCase())} · ${escape(n.input.decision)} · ${escape(n.created_at)}</div><small>${escape(n.input.setup)} · ${escape(n.rule_version)}</small><p>${escape(n.input.note)}</p><p>Deviation: ${escape(n.input.deviations||'None recorded')}</p></article>`).join('');if(after)node('research-notes').insertAdjacentHTML('beforeend',html);else node('research-notes').innerHTML=html||'No observations saved.';journalCursor=r.next_cursor;node('research-more-notes').hidden=!journalCursor;}catch(e){notify(e.message);}}
  function bind(){window.thetaLiveMount?.();node('research-session-refresh')?.addEventListener('click',()=>window.thetaSessionRefresh({manual:true}));node('room-setup')?.addEventListener('change',e=>{activeSetup=e.target.value;riskRevision++;riskResult='';window.thetaPaperPlanClear?.();render();});node('research-symbol').onchange=e=>{window.thetaLiveStop?.();symbol=e.target.value;selected=null;riskRevision++;riskDraft={};riskResult='';selectionNotice='';window.thetaPaperPlanClear?.();data=null;session=null;liveTick=null;liveOptions.clear();sessionMessage='Start live to load today’s closed candles';render();load();};node('research-refresh').onclick=load;node('research-more-notes')?.addEventListener('click',()=>loadNotes(journalCursor));node('research-ema')?.addEventListener('change',e=>{showEma20=e.target.checked;drawChart();});node('research-ema50')?.addEventListener('change',e=>{showEma50=e.target.checked;drawChart();});document.querySelectorAll('[data-timeframe]').forEach(b=>b.onclick=()=>{timeframe=+b.dataset.timeframe;render();});document.querySelectorAll('[data-contract]').forEach(b=>b.onclick=()=>{pickContract(data.chain.contracts.find(r=>r.security_id===b.dataset.contract));});node('research-chain')?.addEventListener('click',async e=>{e.target.disabled=true;notify('Fetching one current-expiry snapshot…');try{await api('dhan/chain',{index:symbol});await load();}catch(error){notify(error.message);e.target.disabled=false;}});
    node('research-risk')?.addEventListener('submit',async e=>{e.preventDefault();const chosen=selected,chosenSymbol=symbol,chosenSetup=activeSetup,revision=++riskRevision;const fields=Object.fromEntries(new FormData(e.target));riskDraft={...fields};for(const [key] of riskFields)fields[key]=Number(fields[key]);fields.expiry_day_allowed=fields.expiry_day_allowed==='true';try{const r=await get('risk',fields);if(revision!==riskRevision||chosenSymbol!==symbol||chosen?.security_id!==selected?.security_id)return;window.thetaPaperPlanReady?.({risk:fields,contract:chosen,symbol,setup:chosenSetup,plan:r});riskResult=`${r.state} · ${r.lots} lots / ${r.quantity} quantity\nTarget premium ₹${fmt(r.target_premium)} · net reward ₹${fmt(r.planned_net_reward)} · net reward / risk ${fmt(r.net_reward_risk_ratio)}R\nPlanned stop loss incl. costs ₹${fmt(r.planned_stop_loss)} · estimated costs ₹${fmt(r.estimated_costs)} · premium paid ₹${fmt(r.premium_paid)}\n${r.reason_codes.join(', ')}\n${r.warning}`;if(node('research-risk-result'))node('research-risk-result').textContent=riskResult;}catch(error){if(revision===riskRevision&&chosenSymbol===symbol&&chosen?.security_id===selected?.security_id){riskResult=error.message;if(node('research-risk-result'))node('research-risk-result').textContent=riskResult;}}});
    node('research-risk')?.addEventListener('invalid',e=>{const details=e.target.closest?.('details');if(details)details.open=true;},true);
    node('research-risk')?.addEventListener('input',e=>{riskRevision++;riskDraft=Object.fromEntries(new FormData(e.currentTarget||e.target));riskResult='';window.thetaPaperPlanClear?.();if(node('research-risk-result'))node('research-risk-result').textContent='Assumptions changed. Recalculate risk.';});
    node('research-coverage')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{const r=await api('dhan/coverage?start='+f.get('start')+'&end='+f.get('end'));node('research-coverage-result').textContent=r.groups.map(g=>`${g.index} ${g.side||'index'} · ${g.rows} rows · ${g.sessions.reduce((n,s)=>n+s.missing,0)} missing weekday-grid minutes · ${g.conflicting_rows} conflicts`).join('\n')+'\n'+r.calendar_validation+'\n'+r.options;}catch(error){node('research-coverage-result').textContent=error.message;}});
    node('research-replay')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const p=Object.fromEntries(new FormData(e.target));p.symbol=symbol;p.clock=p.clock+':00+05:30';try{const r=await get('replay',p);node('research-replay-result').textContent=`${r.status} · ${r.events.length} known 5m events\nOption P&L: unavailable\n${r.gates.join(' · ')}\n${r.scope}`;const slider=node('research-replay-slider');slider.max=Math.max(0,r.events.length-1);slider.value='0';node('research-replay-slider-label').hidden=!r.events.length;slider.oninput=()=>{const event=r.events[+slider.value];node('research-replay-event').textContent=event?`${event.clock} · close ${fmt(event.close)} · price pattern ${event.price_pattern?.state||'Unavailable'} · evidence ${event.state}\n${event.reason_codes.map(explain).join(' · ')}`:'No events in selected range.';};slider.oninput();}catch(error){node('research-replay-result').textContent=error.message;}finally{b.disabled=false;}});
    node('research-note')?.addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const id=e.target.dataset.noteId||(e.target.dataset.noteId=crypto.randomUUID().replaceAll('-',''));const p={...Object.fromEntries(new FormData(e.target)),symbol,id};try{await window.thetaAdminRequest('research/journal',p);e.target.reset();delete e.target.dataset.noteId;notify('Observation saved. This is not a paper fill.');await loadNotes();}catch(error){notify(error.message);}finally{b.disabled=false;}});
  }

  function renderSelectedLive(){
    const el=node('selected-live-observation');if(!el)return;
    const row=liveOptions.get(selected?.security_id);
    if(!row||!selected||row.expiry!==selected.expiry||row.side!==selected.side||row.strike!==selected.strike){el.innerHTML='<p class="research-help">Selected contract: awaiting socket observation. Snapshot values below are not live quotes.</p>';return;}
    const tradeAge=Date.now()-Date.parse(row.trade_at),receiptAge=Date.now()-Date.parse(row.received_at),active=window.thetaLiveIsConnected?.()??window.thetaLiveIsActive?.();
    const recent=active&&row.trade_state==='RECENT_TRADE'&&tradeAge>=0&&tradeAge<=10000&&receiptAge>=0&&receiptAge<=10000;
    el.innerHTML=`<div class="research-meta">${recent?'Recent trade · live socket':'Retained / stale observation'} · quote time unverified</div>${line('Observed LTP',fmt(row.ltp))}${line('Observed bid / ask',fmt(row.bid)+' / '+fmt(row.ask))}${line('Observed spread %',fmt(row.spread_pct))}${line('Observed volume / OI',fmt(row.volume,0)+' / '+fmt(row.oi,0))}<div class="research-meta">Trade ${escape(row.trade_at)} · received ${escape(row.received_at)}</div><p class="research-help">Socket observations do not certify quote freshness or replace your risk-entry assumption.</p>`;
  }
  window.thetaResearchLiveBatch=ticks=>{for(const row of ticks||[])if(row.role==='option'&&row.underlying===symbol&&row.identity_verified){liveOptions.set(row.security_id,row);if(liveOptions.size>100)liveOptions.delete(liveOptions.keys().next().value);}renderSelectedLive();};
  window.thetaResearchLiveReset=()=>{liveOptions.clear();renderSelectedLive();};
  window.thetaResearchLiveState=()=>{renderSelectedLive();window.thetaChartLive?.(liveTick);};
  window.thetaResearchTick=row=>{if(row.key!==symbol)return;liveTick=row;if(current==='research')window.thetaChartLive?.(liveTick);};
  window.thetaSessionRefresh=async({manual=false}={})=>{
    if(sessionLoading||(!manual&&!window.thetaLiveIsActive?.()))return;
    if(typeof window.thetaAdminRequest!=='function'){sessionMessage='Unlock Admin to refresh provider candles and breadth.';if(node('research-session-state'))node('research-session-state').textContent=sessionMessage;return;}
    if(node('research-session-refresh'))node('research-session-refresh').disabled=true;
    const requested=symbol,requestedId=requestId,contractId=selected?.security_id||'';sessionLoading=true;sessionMessage='Fetching current-session provider candles…';if(node('research-session-state'))node('research-session-state').textContent=sessionMessage;
    try{const result=await window.thetaAdminRequest('research/session',{symbol:requested,contract_id:contractId});if(symbol!==requested||requestedId!==requestId)return;session=result;if(result.workspace){data={...data,...result.workspace};if(selected){const fresh=result.workspace.chain.contracts.find(c=>c.security_id===contractId);selected=fresh||{...selected,last_price:null,bid:null,ask:null,spread_pct:null,iv:null,greeks:null,freshness:'UNAVAILABLE'};selectionNotice=fresh?'':'Selected contract is absent from this snapshot. Quotes unavailable; choose another contract explicitly.';}selectionPending=false;}sessionMessage=`${result.session_date} · ${result.candles.length}/${result.expected_minutes} closed minutes · ${result.missing_minutes} gaps · ${result.freshness.state} · received ${result.received_at} · missing ${(result.missing_timestamps||[]).slice(0,8).map(t=>new Date(t*1000).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata'})).join(', ')||'none'}${result.missing_minutes>8?' …':''}`;}
    catch(e){if(symbol===requested&&requestedId===requestId)sessionMessage='Current-session refresh failed: '+e.message+' · retained candles are not certified current';}
    finally{sessionLoading=false;if(node('research-session-refresh'))node('research-session-refresh').disabled=false;if(node('research-session-state'))node('research-session-state').textContent=sessionMessage;if(symbol===requested&&requestedId===requestId&&(current==='research'||current==='options'))render();}
  };
  setInterval(()=>{window.thetaSessionRefresh();if(current==='research'){if(session&&node('research-session-state')){const age=Date.now()-Date.parse(session.received_at);node('research-session-state').textContent=sessionMessage+(age>90000?' · REFRESH STALE':'');}drawChart();}},60000);
  window.thetaResearchSelectSymbol=value=>{if(!['nifty','banknifty'].includes(value))return;const select=node('research-symbol');if(select?.onchange){select.value=value;select.onchange({target:select});}};
  window.thetaResearchSnapshot=()=>({data,selected,symbol,current,context:session?.context});
  function pickContract(row){if(!row)return;selected=row;riskRevision++;riskDraft={};riskResult='';selectionNotice='';selectionPending=true;window.thetaPaperPlanClear?.();render();load();}
  window.thetaResearchPickContract=row=>{pickContract(data?.chain?.contracts.find(c=>c.security_id===row.security_id)||{...row,last_price:row.ltp,freshness:row.quote_state});};
  window.thetaResearchShow=name=>{if(!pages.includes(name)){window.thetaChartDispose?.();current=name;window.thetaDashboardMount?.();return;}current=name;render();if(!data&&!loading)load();};
  window.addEventListener('resize',()=>{if(current==='research')drawChart();});
  window.thetaResearchShow(location.hash.slice(1)||'research');
})();
